151	    pub fn as_slice(&self) -> ChunkSlice<'_> {
152	        ChunkSlice {
153	            chars: self.chars,
154	            chars_utf16: self.chars_utf16,
155	            newlines: self.newlines,
156	            tabs: self.tabs,
157	            text: &self.text,
158	        }
159	    }
