167	    pub fn chars(&self) -> Bitmap {
168	        self.chars
169	    }
170	
171	    #[inline(always)]
172	    pub fn tabs(&self) -> Bitmap {
173	        self.tabs
174	    }
175	
176	    #[inline(always)]
177	    pub fn newlines(&self) -> Bitmap {
178	        self.newlines
179	    }
