365	    /// Get number of UTF-16 code units in last line
366	    #[inline(always)]
367	    pub fn last_line_len_utf16(&self) -> u32 {
368	        (self.chars_utf16 & saturating_shr_mask(self.newlines.leading_zeros())).count_ones()
369	    }
