478	    pub fn offset_utf16_to_offset(&self, target: OffsetUtf16) -> usize {
479	        if target.0 == 0 {
480	            0
481	        } else {
482	            #[cfg(not(test))]
483	            let chars_utf16 = self.chars_utf16;
